 namespace {
 string HexToString(const string& str) {
   string parsed;
   if (str[0] != '0' || str[1] != 'x') {
     fprintf(stderr, "Invalid hex input %s.  Must start with 0x\n",
             str.c_str());
     throw "Invalid hex input";
   }

   for (unsigned int i = 2; i < str.length();) {
     int c;
     sscanf(str.c_str() + i, "%2X", &c);
     parsed.push_back(c);
     i += 2;
   }
   return parsed;
 }
 }  // namespace

