+bool LRUCacheShard::Ref(Cache::Handle* h) {
+  LRUHandle* handle = reinterpret_cast<LRUHandle*>(h);
+  MutexLock l(&mutex_);
+  if (handle->InCache()) {
+    if (handle->refs == 1) {
+      LRU_Remove(handle);
+    }
+    handle->refs++;
+    return true;
+  }
+  return false;
+}
