 size_t MemTableList::ApproximateMemoryUsage() {
   size_t size = 0;
   for (list<MemTable*>::iterator it = memlist_.begin();
        it != memlist_.end(); ++it) {
     size += (*it)->ApproximateMemoryUsage();
   }
   return size;
