+// returns true(i.e. key-value to be deleted) if its TS has expired based on ttl
+bool DBWithTTL::DeleteByTS(
+    void* args,
+    int level,
+    const Slice& key,
+    const Slice& old_val,
+    std::string* new_val,
+    bool* value_changed) {
+  return IsStale(old_val, *(int32_t*)args);
