   // cache_entry_stats_collector_ field is const after constructor
   // and ->GetStats does its own synchronization, which also suffices for
   // cache_entry_stats_.

   if (!cache_entry_stats_collector_) {
     return;  // nothing to do (e.g. no block cache)
