+  Status s = ListAllWALFiles(dbname_, &walFiles, kAliveLogFile);
+  if (!s.ok()) {
+    return s;
+  }
+  //  list wal files in archive dir.
+  s = ListAllWALFiles(GetArchivalDirectoryName(), &walFiles, kArchivedLogFile);
