    leveldb::Options opt;
    opt.create_if_missing = false;
    return opt;
  }

  virtual bool NoDBOpen() {
    return false;
  }

  virtual ~LDBCommand() {
    if (db_ != NULL) {
      delete db_;
      db_ = NULL;
    }

  void Run() {
    if (!exec_state_.IsNotStarted()) {
      return;
    }

   if (db_ == NULL && !NoDBOpen()) {
      OpenDB();
    }

    DoCommand();
    if (exec_state_.IsNotStarted()) {
      exec_state_ = LDBCommandExecuteResult::SUCCEED("");
    }

    if (db_ != NULL) {
      CloseDB ();
    }
  }

  void CloseDB () {
    if (db_ != NULL) {
      delete db_;
      db_ = NULL;
    }
  }

  Status GetOldNumOfLevels(leveldb::Options& opt, int* levels);
};

