   Status s;
   // Wait until the compaction completes
   MutexLock l(&mutex_);
   while (imm_.size() > 0 && bg_error_.ok()) {
     bg_cv_.Wait();
   }
   if (imm_.size() != 0) {
     s = bg_error_;
   }
   return s;
 }

