+        t.tm_year + 1900, t.tm_mon + 1, t.tm_mday, t.tm_hour, t.tm_min,
+        t.tm_sec, static_cast<int>(log->now_tv.tv_usec), log->message);
+  }
+  logs_.clear();
+}
