   if (!FLAGS_verbose) {
     return;
   }
   std::string tmp;
   tmp.reserve(sz * 2 + 16);
   char buf[4];
   for (size_t i = 0; i < sz; i++) {
     snprintf(buf, 4, "%X", value[i]);
     tmp.append(buf);
   }
   fprintf(stdout, "[CF %d] %" PRIi64 " == > (%" ROCKSDB_PRIszt ") %s\n", cf,
           key, sz, tmp.c_str());
 }

