  for (uint32_t len = 2; len < kMaxCycleLength; len++) {
    // Set up a long wait for chain like this:
    //
    // T1 -> T2 -> T3 -> ... -> Tlen
    std::vector<Transaction*> txns(len);

    for (uint32_t i = 0; i < len; i++) {
