+    TimestampRecoveryHandler recovery_handler(running_ts_sz, record_ts_sz);
+    status = batch->Iterate(&recovery_handler);
+    if (!status.ok()) {
+      return status;
+    } else {
+      batch = recovery_handler.TransferNewBatch();
+      WriteBatchInternal::SetSequence(batch.get(), sequence);
+    }
+  }
+  return Status::OK();
+}
