+  const Slice key = cache_key.AsSlice();
+
+  CachableEntry<std::string> blob_entry;
+  const Status s = GetBlobFromCache(key, &blob_entry);
+
+  if (s.ok() && blob_entry.GetValue() != nullptr) {
+    return true;
+  }
+
+  return false;
+}
